ALL = SYSTEMS + DISEASES

def home(request):
    query = request.GET.get("q", "").strip()
    q = query.lower()
    results = [x for x in ALL if q and q in (x["title"] + " " + x["text"] + " " + x["tag"]).lower()]
    return render(request, "home.html", {"systems": SYSTEMS, "diseases": DISEASES, "query": query, "results": results})

